use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-reverse-leaf176";
fn read(n:&str)->Value{serde_json::from_slice(&fs::read(format!("{R}/{n}")).unwrap()).unwrap()}fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert!(!Path::new(&format!("{R}/capture")).exists());let initial=format!("{R}/initial-code-audit");fs::create_dir(&initial).unwrap();let mut pins=read("capture-pins.json");for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}for n in["codegen.json","capture-pins.json","capture-plan.json","capture-design.md"]{fs::copy(format!("{R}/{n}"),format!("{initial}/{n}")).unwrap();}let assembly=format!("{R}/codegen/on-forward-caller.s");let text=fs::read_to_string(&assembly).unwrap();assert_eq!(text.matches("vpmadd52").count(),250);let calls=text.lines().filter(|l|l.contains("call")&&l.contains("reverse_leaf")).count();assert_eq!(calls,1);let nm=Command::new("nm").args(["-S","--size-sort","--defined-only",&format!("{R}/on-probe")]).output().unwrap();assert!(nm.status.success());let nm=String::from_utf8(nm.stdout).unwrap();let hits=nm.lines().filter(|l|l.contains("BorrowedG2")&&l.contains("Caller3run")).collect::<Vec<_>>();assert_eq!(hits.len(),1);let mut code=read("codegen.json");assert_eq!(code.as_array().unwrap().len(),3);code.as_array_mut().unwrap().push(json!({"arm":"on","nm":hits[0],"file":assembly,"sha256":hash(&assembly),"static_IFMA_sites":250,"instruction_lines":text.lines().filter(|l|l.split_once(':').is_some_and(|(s,_)|!s.trim().is_empty()&&s.trim().chars().all(|c|c.is_ascii_hexdigit()))).count(),"scope":"actual BorrowedG2::run owns inlined forward/tail caller","direct_reverse_leaf_call_sites":calls}));assert_eq!(code.as_array().unwrap().iter().filter(|c|c["arm"]=="on").map(|c|c["static_IFMA_sites"].as_u64().unwrap()).sum::<u64>(),1450);fs::write(format!("{R}/codegen.json"),serde_json::to_vec_pretty(&code).unwrap()).unwrap();let mut design=fs::read_to_string(format!("{R}/capture-design.md")).unwrap();design.push_str("\nNative code audit before first capture: LLVM inlined the remaining forward/tail body into BorrowedG2::run, so the initial borrowed-apply-name-only census found ON reverse leaf1200IFMA but no separate forward symbol. Its original three-row code metadata and pin set are retained in initial-code-audit. Supplement the actual caller disassembly (250IFMA,one direct leaf call site), giving combined1450as in both controls; seal all four actual bodies before timing. No source/layout/gate/measurement or successful capture changes or repeats. Whole-symbol sizes/sites do not establish dynamic spills or cache behavior.\n");fs::write(format!("{R}/capture-design.md"),design).unwrap();for p in[format!("{R}/codegen.json"),format!("{R}/capture-design.md"),assembly,format!("{R}/seal-forward-caller.rs"),format!("{R}/seal-forward-caller"),format!("{R}/initial-code-audit/codegen.json"),format!("{R}/initial-code-audit/capture-pins.json"),format!("{R}/initial-code-audit/capture-plan.json"),format!("{R}/initial-code-audit/capture-design.md")]{pins.as_object_mut().unwrap().insert(p.clone(),json!(hash(&p)));}fs::write(format!("{R}/capture-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();println!("Supplemental native audit PASS before capture: actual ON caller250+reverse1200=1450IFMA,oneleafcall;four disassemblies,initialmetadataretained;no candidate/gate change");}
